// ─── Parse agreement item ────────────────────────────────────────────────
const item = $input.first().json.data.items[0];
if (!item) throw new Error('Monday item not found in response');

const cols = {};
for (const col of item.column_values) {
  try { cols[col.id] = col.value ? JSON.parse(col.value) : null; }
  catch(e) { cols[col.id] = col.value; }
  cols[col.id + '__text'] = col.text;
}

// ─── Core client info ────────────────────────────────────────────────────
const clientName   = item.name;
const firstName    = cols['text_mm1sys6v__text'] || '';
const lastName     = cols['short_text1oxj0f3m__text'] || '';
const clientEmail  = cols['email_mm1st5e9__text'] || '';
const dateSigned   = (cols['date_mm1s7q2s'] || {}).date || null;
const today        = new Date().toISOString().split('T')[0];

// ─── Map service checkboxes → Client Database dropdown labels ─────────────
const svcSet = new Set();
const chk = id => cols[id] && cols[id].checked === 'true';
if (chk('booleankz6r6wfo') || chk('booleaneier0pdj')) svcSet.add('Strategy');
if (cols['multi_select5y87oaju__text'])                svcSet.add('Creative');
if (chk('booleantdu79dpj'))                            svcSet.add('Ads');
if (chk('boolean0n215rqt') || chk('booleanbto2nwfp'))  svcSet.add('LI Outreach');
if (chk('booleanltdvfg3r'))                            svcSet.add('Content');
const services = [...svcSet];

// ─── Slack channel name (lowercase, dashes) ───────────────────────────────
const slackChannelName = clientName
  .toLowerCase()
  .replace(/[^a-z0-9\s-]/g, '')
  .replace(/\s+/g, '-')
  .replace(/-+/g, '-')
  .slice(0, 80);

// ─── Build Monday Client Database mutation ───────────────────────────────
const clientDBCols = {
  status58: { label: 'Onboarding' },
  date_agreement_signed: { date: today },
  date4: { date: dateSigned || today }
};
if (services.length > 0) clientDBCols.dropdown0 = { labels: services };

const createClientDBBody = JSON.stringify({
  query: 'mutation { create_item(' +
    'board_id: 1050013805, ' +
    'group_id: "topics", ' +
    'item_name: ' + JSON.stringify(clientName) + ', ' +
    'column_values: ' + JSON.stringify(JSON.stringify(clientDBCols)) +
    ') { id } }'
});

// ─── Build Campaign Calendar duplication mutation ────────────────────────
const calendarName = clientName + ' Campaign Calendar';
const duplicateCalendarBody = JSON.stringify({
  query: 'mutation { duplicate_board(' +
    'board_id: 1769173441, ' +
    'duplicate_type: duplicate_board_with_pulses, ' +
    'board_name: ' + JSON.stringify(calendarName) + ', ' +
    'workspace_id: 5013168' +
    ') { board { id name } } }'
});

// ─── Build Slack channel creation body ───────────────────────────────────
const slackCreateChannelBody = JSON.stringify({
  name: slackChannelName,
  is_private: false
});

// ─── Output ───────────────────────────────────────────────────────────────
return [{ json: {
  itemId:               item.id,
  clientName,
  firstName,
  lastName,
  clientEmail,
  dateSigned:           dateSigned || today,
  agreementPaidDate:    today,
  services,
  slackChannelName,
  calendarName,
  createClientDBBody,
  duplicateCalendarBody,
  slackCreateChannelBody
}}];

